function norm(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,' ').trim();}
function nAlias(v){return norm(v).replace(/\burina simples\b/g,'eas').replace(/\burina tipo 1\b/g,'eas')
  .replace(/\burina tipo i\b/g,'eas').replace(/\bt4l\b/g,'t4 livre').replace(/\bbeta-hcg\b/g,'beta hcg')
  .replace(/\bfero\b/g,'ferro').replace(/\brubela\b/g,'rubeola');}
function getAliases(e){return[e.nome,...(Array.isArray(e.aliases)?e.aliases:[])].filter(Boolean).map(nAlias);}
function findExams(inputText){
  const t=nAlias(inputText),found=[],used=new Set();
  for(const e of examCatalog){if(used.has(e.id))continue;
    for(const a of getAliases(e)){if(a.length>=3&&t.includes(a)){found.push(e);used.add(e.id);break;}}}
  return found;}

