    const toAdd=newExams.filter(e=>!existIds.has(e.id));
    if(toAdd.length>0){budgetSnapshot.exams=[...budgetSnapshot.exams,...toAdd];
      budgetSnapshot.total=budgetSnapshot.exams.reduce((s,e)=>s+(Number(e.valor)||0),0);
      budgetSnapshot.updated_at=new Date().toISOString();}
  } else {
    budgetSnapshot={exams:newExams,total:newExams.reduce((s,e)=>s+(Number(e.valor)||0),0),
