  'manha','manhã','tarde','horario','horário','resultado','coleta','particular','convenio','convênio',
  'hemograma','glicemia','tsh','vitamina','colesterol','psa','urina','fezes'];

function isValidName(rawText){
  const t=rawText.trim();
  if(t.length<2||t.length>80)return false;
  const words=t.split(/\s+/);
  if(words.length<1||words.length>5)return false;
  // Primeira palavra deve começar com letra maiúscula (nome próprio)
  if(!/^[A-ZÁÉÍÓÚÀÃÕÂÊÔÜ]/u.test(words[0]))return false;
  const normT=t.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim();
  // Não pode conter termos operacionais
  if(OP_TERMS.some(op=>normT.includes(op)))return false;
  // Não pode ser só números ou símbolos
  if(/^[\d\s\W]+$/.test(t))return false;
  return true;
}

function extractDate(t){
  const m=t.match(/\b(\d{1,2})[\/\-](\d{1,2})(?:[\/\-](\d{2,4}))?\b/);
  if(m)return`${m[1]}/${m[2]}${m[3]?'/'+m[3]:''}`;
  if(t.includes('amanha')||t.includes('amanhã'))return'amanhã';
  if(t.includes('hoje'))return'hoje';
  if(t.includes('segunda'))return'próxima segunda-feira';
  if(t.includes('terca')||t.includes('terça'))return'próxima terça-feira';
  if(t.includes('quarta'))return'próxima quarta-feira';
  if(t.includes('quinta'))return'próxima quinta-feira';
  if(t.includes('sexta'))return'próxima sexta-feira';
  if(t.includes('sabado')||t.includes('sábado'))return'próximo sábado';
  return null;
}
function extractTime(t){
  const m=t.match(/\b(\d{1,2})(?::(\d{2}))?\s*(?:h|hs|horas?)?\b/);
  if(m&&parseInt(m[1])>=6&&parseInt(m[1])<=18)return`${m[1].padStart(2,'0')}:${(m[2]||'00')}`;
  if(t.includes('manha')||t.includes('manhã'))return'manhã';
  if(t.includes('tarde'))return'tarde';
  return null;
}

