    customer_name:item.customer_name||ctx.paciente_nome||'Cliente WhatsApp',
    message_text:item.message_text,bot_reply:item.bot_response,
    is_handoff:resp.handoff||false,
    desired_status:resp.handoff?'pending':'open',
    contact_id:ctx.chatwoot_contact_id,conversation_id_cw:ctx.chatwoot_conversation_id,
    base_url:base,account_id:accId,inbox_id:inboxId,api_token:token}}}];

const item=$input.item.json;
const result=$json;
// Chatwoot retorna { payload: [contacts] } em /contacts/search
const contacts=(result.payload&&Array.isArray(result.payload))?result.payload:
  (Array.isArray(result)?result:[]);
const found=contacts.find(c=>{
  const p=String(c.phone_number||'').replace(/\D/g,'');
  const target=String(item.phone_normalized||'').replace(/\D/g,'');
  return p.endsWith(target)||target.endsWith(p);
});
const contactId=found?String(found.id):null;
return[{json:{...item,
  chatwoot_contact_id:contactId||item.chatwoot_contact_id||(item.conversation_context||{}).chatwoot_contact_id||null,
  _cw_contact_found:Boolean(contactId),_cw_need_create_contact:!contactId&&!item.chatwoot_contact_id&&!(item.conversation_context||{}).chatwoot_contact_id}}];

const item=$input.item.json;
const conv=$json;
// Considera válida se status for open ou pending
const status=String(conv.status||'').toLowerCase();
const isValid=['open','pending'].includes(status);
return[{json:{...item,_cw_conversa_valida:isValid,_cw_conversa_status:status}}];

